import express from 'express';
import fs from 'node:fs';
import { Readable } from 'node:stream';
import path from 'node:path';
import { renderMenu } from './menu.js';
import { currentMenu, getPage, isStorageConfigured, publishMenu } from './storage.js';

const app = express();

// src/ and dist/ both sit one level below the project root.
const publicDir = path.join(import.meta.dirname, '..', 'public');
app.use(express.static(publicDir));

// The bundled menu is generated by `npm run menu`. It is shown until a PDF is
// uploaded at /admin, after which the menu is served from S3.
const bundledPageCount = fs
  .readdirSync(path.join(publicDir, 'menu'))
  .filter((name) => /^page-\d+\.jpg$/.test(name)).length;
let menuUpdating = false;

async function menuPageUrls(): Promise<string[]> {
  let menu = null;
  try {
    menu = await currentMenu();
  } catch (error) {
    console.error('Could not load the uploaded menu, showing the bundled one:', error);
  }

  return menu
    ? Array.from({ length: menu.pages }, (_, index) => `/menu/${menu.version}/page-${index + 1}.jpg`)
    : Array.from({ length: bundledPageCount }, (_, index) => `/menu/page-${index + 1}.jpg`);
}

app.get('/', async (_request, response) => {
  const pages = (await menuPageUrls())
    .map(
      (url, index) =>
        `<img src="${url}" alt="Menu page ${index + 1}" width="1600" height="1131"${index > 0 ? ' loading="lazy"' : ''}>`,
    )
    .join('\n');

  response.type('html').send(`<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Escape Menu</title>
  <style>
    body { margin: 0; background: #d8c39b; }
    main { max-width: 1200px; margin: 0 auto; }
    img { display: block; width: 100%; height: auto; }
    a { display: block; padding: 16px; text-align: center; color: #fff; font: 16px system-ui, sans-serif; }
  </style>
</head>
<body>
  <main>
    ${pages}
  </main>
</body>
</html>`);
});

app.get('/admin', (_request, response) => {
  response.type('html').send(`<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Update Menu</title>
  <style>
    body { max-width: 480px; margin: 48px auto; padding: 0 16px; font: 16px system-ui, sans-serif; }
    label { display: block; margin-top: 16px; }
    input, button { display: block; margin-top: 4px; font: inherit; }
    button { margin-top: 24px; padding: 8px 16px; }
  </style>
</head>
<body>
  <h1>Update menu PDF</h1>
  <form id="upload">
    <label>Admin token <input type="password" name="token" required></label>
    <label>Menu PDF <input type="file" name="pdf" accept="application/pdf" required></label>
    <button type="submit">Upload</button>
  </form>
  <p id="status" role="status"></p>
  <script>
    const form = document.getElementById('upload');
    const status = document.getElementById('status');
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const button = form.querySelector('button');
      button.disabled = true;
      status.textContent = 'Uploading and rendering pages…';
      try {
        const response = await fetch('/api/menu', {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/pdf',
            Authorization: 'Bearer ' + form.token.value,
          },
          body: form.pdf.files[0],
        });
        const result = await response.json();
        status.innerHTML = response.ok
          ? 'Updated ' + result.pages + ' pages. <a href="/">View menu</a>'
          : 'Failed: ' + result.error;
      } catch (error) {
        status.textContent = 'Failed: ' + error.message;
      } finally {
        button.disabled = false;
      }
    });
  </script>
</body>
</html>`);
});

app.put(
  '/api/menu',
  (request, response, next) => {
    const token = process.env.ADMIN_TOKEN;
    if (!token) {
      response.status(503).json({ error: 'Menu uploads are disabled: ADMIN_TOKEN is not set' });
      return;
    }
    if (request.get('authorization') !== `Bearer ${token}`) {
      response.status(401).json({ error: 'Invalid admin token' });
      return;
    }
    next();
  },
  express.raw({ type: 'application/pdf', limit: '50mb' }),
  async (request, response) => {
    const pdf: unknown = request.body;
    if (!Buffer.isBuffer(pdf) || pdf.subarray(0, 5).toString('latin1') !== '%PDF-') {
      response.status(400).json({ error: 'Send a PDF with Content-Type: application/pdf' });
      return;
    }
    if (!isStorageConfigured()) {
      response.status(503).json({ error: 'Menu uploads are disabled: S3_BUCKET is not set' });
      return;
    }
    if (menuUpdating) {
      response.status(409).json({ error: 'Another menu update is in progress' });
      return;
    }

    menuUpdating = true;
    try {
      let pages: Buffer[];
      try {
        pages = await renderMenu(new Uint8Array(pdf));
      } catch (error) {
        console.error('Menu render failed:', error);
        response.status(422).json({ error: 'Could not render that PDF' });
        return;
      }

      const menu = await publishMenu(pdf, pages);
      response.json({ pages: menu.pages });
    } catch (error) {
      console.error('Menu upload failed:', error);
      response.status(502).json({ error: 'Could not save the menu to storage' });
    } finally {
      menuUpdating = false;
    }
  },
);

app.get('/menu/:version/:file', async (request, response, next) => {
  const { version, file } = request.params;
  const pageNumber = Number(/^page-(\d+)\.jpg$/.exec(file)?.[1]);
  if (!/^\d+$/.test(version) || !pageNumber || !isStorageConfigured()) {
    next();
    return;
  }

  try {
    const page = await getPage(version, pageNumber);
    if (!page) {
      next();
      return;
    }
    // Versioned pages never change, so browsers can keep them indefinitely.
    response.set({ 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=31536000, immutable' });
    // In Node the SDK returns the body as a Readable stream.
    (page as Readable).pipe(response);
  } catch (error) {
    next(error);
  }
});

app.get('/api/health', (_request, response) => {
  response.json({
    status: 'ok',
  });
});

app.get('/api/version', (_request, response) => {
  response.json({
    version: process.env.APP_VERSION ?? 'development',
  });
});

export default app;
